import { Metadata } from "next";
import PNRDetailClient from "./PNRDetailClient";

// 1. Dynamic SEO Metadata for PNR Result Page (Robots set to noindex for privacy)
export async function generateMetadata({ params }: { params: Promise<{ pnr: string }> }): Promise<Metadata> {
  const resolvedParams = await params;
  const pnr = resolvedParams.pnr;
  
  return {
    title: `PNR Status ${pnr} | Live Confirmation Probability - Trayago`,
    description: `Check live seat allocation and confirmation probability for IRCTC PNR ${pnr}. Get real-time updates and AI-driven travel probability predictions.`,
    alternates: {
      canonical: `https://www.trayago.in/pnr/${pnr}`,
    },
    openGraph: {
      type: "website",
      title: `PNR Status ${pnr} — Trayago`,
      description: `Check live seat allocation and confirmation probability for IRCTC PNR ${pnr}.`,
      url: `https://www.trayago.in/pnr/${pnr}`,
      siteName: "Trayago",
      images: [{ url: "/og-image.png", width: 1200, height: 630, alt: "Trayago PNR Status" }],
    },
    twitter: {
      card: "summary_large_image",
      title: `PNR Status ${pnr} — Trayago`,
      description: `Check live seat allocation and confirmation probability for IRCTC PNR ${pnr}.`,
      images: ["/og-image.png"],
    },
    robots: {
      index: false, // DO NOT INDEX individual passenger PNR pages to protect privacy
      follow: false,
    }
  };
}

interface PageProps {
  params: Promise<{ pnr: string }>;
}

export default function PNRDetailPage({ params }: PageProps) {
  // 2. Structured Data Schema
  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    "itemListElement": [
      {
        "@type": "ListItem",
        "position": 1,
        "name": "Home",
        "item": "https://www.trayago.in"
      },
      {
        "@type": "ListItem",
        "position": 2,
        "name": "PNR Status Checker",
        "item": "https://www.trayago.in/pnr"
      },
      {
        "@type": "ListItem",
        "position": 3,
        "name": "PNR Details",
        "item": `https://www.trayago.in/pnr`
      }
    ]
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }}
      />
      <PNRDetailClient params={params} />
    </>
  );
}
